class DocumentStore:
    def __init__(self, rows):
        self._rows = rows

    def fetch_by_id(self, doc_id):
        return self._rows.get(doc_id)

    def fetch_by_id_and_tenant(self, doc_id, tenant_id):
        row = self._rows.get(doc_id)
        if row and row["tenant_id"] == tenant_id:
            return row
        return None
